function minWindow(s: string, t: string): string {
  console.log(s, t);

  const tReq: { [k: string]: number } = {},
    tWin: { [k: string]: number } = {};

  for (let i = 0; i < t.length; i++) {
    if (tReq[t[i]]) {
      tReq[t[i]]++;
    } else {
      tReq[t[i]] = 1;
      tWin[t[i]] = 0;
    }
  }

  console.log(tReq, tWin);

  let tCount = 0;
  let minLeft = 0,
    minRight = s.length;
  let found = false;
  for (let right = 0, left = 0; right < s.length; right++) {
    const c = s[right];

    if (tReq[c] !== undefined) {
      tWin[c]++;

      if (tWin[c] <= tReq[c]) tCount++;
    }

    while (tCount === t.length) {
      console.log(
        `(${right}) Window: ${s.slice(left, right + 1)} ${right - left + 1}`,
      );
      const cl = s[left];
      if (tReq[cl] !== undefined) {
        // console.log(`Current: ${minWin} (${minWin?.length})`);
        // console.log(`New: ${s.slice(left, right + 1)} ${right - left + 1}`);
        if (right - left + 1 < minRight - minLeft + 1) {
          minLeft = left;
          minRight = right;
          found = true;
        }

        tWin[cl]--;

        console.log(tWin, tReq);

        if (tWin[cl] < tReq[cl]) tCount--;
      }
      left++;
    }
  }

  return found ? s.slice(minLeft, minRight + 1) : "";
}

console.log(
  "---- RESULT",
  minWindow("ADOBECODEBANC", "ABC"),
  '"BANC"',
  "----\n",
);

console.log("---- RESULT", minWindow("a", "a"), '"a"', "----\n");

console.log("---- RESULT", minWindow("a", "aa"), '""', "----\n");

console.log("---- RESULT", minWindow("bba", "ab"), '"ba"', "----\n");

console.log("---- RESULT", minWindow("aab", "aab"), '"aab"', "----\n");

